/**
 * Colour tables and the frame encoding for `PaletteDisplay`.
 */

/**
 * The 64 colours of the 2C02 video chip, as `0xRRGGBB`, indexed by the 6-bit
 * colour number the chip outputs ($00-$3F). These are the first 64 entries of
 * `2C02G_U_wiki.pal` from the NESdev wiki's "PPU palettes" page, generated by
 * pally v0.23.0 (github.com/Gumball2415/pally, MIT-0) from a model of the
 * chip's composite output, so there is no attribution requirement.
 */
// biome-ignore format: eight colours per row, as the chip's palette is laid out
export const PALETTE_2C02: readonly number[] = Object.freeze([
  0x575757, 0x000c8e, 0x0800a6, 0x340096, 0x550061, 0x630015, 0x5a0000, 0x3c0e00,
  0x112800, 0x003b00, 0x004200, 0x003a05, 0x002652, 0x000000, 0x000000, 0x000000,
  0xa5a5a5, 0x0041d9, 0x2f1eff, 0x6704f2, 0x9400b4, 0xaa0057, 0xa31800, 0x803900,
  0x4b5b00, 0x137600, 0x008100, 0x007923, 0x006288, 0x000000, 0x000000, 0x000000,
  0xffffff, 0x4a9fff, 0x797eff, 0xaf63ff, 0xdd55ff, 0xf757c2, 0xf76a63, 0xdc8810,
  0xaea900, 0x78c400, 0x4ad211, 0x2fcf64, 0x2fbdc4, 0x414141, 0x000000, 0x000000,
  0xffffff, 0xb9ddff, 0xcad1ff, 0xdec6ff, 0xf0c0ff, 0xfcc0ee, 0xfdc6ca, 0xf5d0aa,
  0xe4dd95, 0xd0e892, 0xbdeea2, 0xb2eec0, 0xb0e8e3, 0xb3b3b3, 0x000000, 0x000000,
]);

/**
 * The colour index of every pixel of a `PaletteDisplay`, row by row, from the
 * string its state holds. Pixels never written are 0.
 *
 * The state is one character per pixel (its colour index as the char code),
 * `width * height` of them, followed by the pixels written in raster order
 * since: character `size + i` replaces pixel `i`. A write at the next raster
 * position is an append, which keeps a frame drawn pixel by pixel linear; the
 * display folds the tail back in once it covers the whole frame.
 */
export function paletteFrame(pixels: string, width: number, height: number): Uint8Array {
  const size = width * height;
  const frame = new Uint8Array(size);
  if (pixels.length < size) return frame;
  const drawn = Math.min(pixels.length - size, size);
  for (let i = 0; i < drawn; i++) frame[i] = pixels.charCodeAt(size + i);
  for (let i = drawn; i < size; i++) frame[i] = pixels.charCodeAt(i);
  return frame;
}
